🐛 Bug
I think it's a small problem but I still can't future it out ..I want to accomplish inference feature using libtorch and OpenCV . So I downloaded the last libtorch(GPU) from Pytorch.org. And also build OpenCV(4.0.0) from source.
When I build libtorch app and OpenCV app with cmake independently, it succeeds.
And when I build libtorch and OpenCV together and don't use 'imread()' function,it succeeds. And the code works in GPU(speed faster than CPU):
#include <opencv2/opencv.hpp>
#include "torch/script.h"
#include "torch/torch.h"

#include <iostream>
#include <memory>
#include <ctime>

using namespace std;
using namespace cv;

int main(int argc, const char* argv[])
{
    if (argc != 2) {
        std::cerr << "usage: example-app <path-to-exported-script-module>\n";
        return -1;
    }

    std::shared_ptr<torch::jit::script::Module> module = torch::jit::load(argv[1]);

    std::vector<torch::jit::IValue> inputs;
    inputs.push_back(torch::ones({1,3,224,224}).to(at::kCUDA));

    module->to(at::kCUDA);
    // inputs.at[0].to(at::kCUDA);
    double timeStart = (double)getTickCount();

    for(int i = 0 ; i < 1000 ; i++)
        at::Tensor output = module->forward(inputs).toTensor();

    double nTime = ((double)getTickCount() - timeStart) / getTickFrequency();

    cout << "Time used:" << nTime*1000 << " ms" << endl;
}
